using System.Collections.Generic;
using UnityEngine;

namespace SpectreEX
{
    // Plays the original Spectre VR MIDI soundtrack (rendered to OGG through GeneralUser GS by
    // Tools/fluid_render.py, generated by Tools/import_original.py). Levels draw from the music styles
    // ticked in Options; the menu plays 5THEME (song 24001). M toggles music, N skips the track.
    public class MusicPlayer : MonoBehaviour
    {
        static MusicPlayer instance;
        public static MusicPlayer Instance
        {
            get
            {
                if (instance == null) instance = FindFirstObjectByType<MusicPlayer>();
                return instance;
            }
            private set => instance = value;
        }

        public float volume = 0.45f;
        const string MenuTheme = "5THEME";

        AudioSource source;
        List<string> playlist = new List<string>();
        int trackIndex;
        bool muted;

        void Awake()
        {
            Instance = this;
            source = gameObject.AddComponent<AudioSource>();
            source.spatialBlend = 0f;
            source.loop = true;
            source.volume = volume;
            source.ignoreListenerPause = true;
        }

        public void PlayMenuTheme()
        {
            if (!GameSettings.MusicOn) source.Stop();
            else if (source.clip == null || source.clip.name != MenuTheme || !source.isPlaying) PlayTrack(MenuTheme);
        }

        public void Stop() => source.Stop();

        public void PlayForLevel(int level)
        {
            playlist = GameSettings.Playlist();
            if (playlist.Count == 0) { source.Stop(); return; }
            PlayIndex(level - 1);
        }

        // A matrix level's song (null = the level has none, or no ticked style covers it)
        public void PlayTrackOrStop(string name)
        {
            if (string.IsNullOrEmpty(name)) source.Stop();
            else PlayTrack(name);
        }

        // Esc menu over a running game: hold the level's song where it is
        public void PauseGameMusic() => source.Pause();
        // Carry on with the level's song, or change to it if settings moved it (null keeps the playlist's)
        public void ResumeGameMusic(string song)
        {
            if (!GameSettings.MusicOn) { source.Stop(); return; }
            if (song != null && (source.clip == null || source.clip.name != song)) { PlayTrack(song); return; }
            if (muted) return;
            source.UnPause();
            if (!source.isPlaying) source.Play();
        }

        public void PlayTrack(string name, bool loop = true)
        {
            if (!GameSettings.MusicOn) { source.Stop(); return; }
            var clip = Resources.Load<AudioClip>("Music/" + name);
            if (clip == null) { Debug.LogWarning("Spectre VR-EX: missing music " + name); return; }
            source.clip = clip;
            source.loop = loop;
            if (!muted) source.Play();
        }

        void PlayIndex(int i)
        {
            if (playlist.Count == 0) return;
            trackIndex = ((i % playlist.Count) + playlist.Count) % playlist.Count;
            PlayTrack(playlist[trackIndex]);
        }

        void Update()
        {
            if (GameKeys.Music.Pressed)
            {
                muted = !muted;
                if (muted) source.Pause(); else source.UnPause();
                if (!muted && !source.isPlaying) source.Play();
            }
            if (GameKeys.NextTrack.Pressed && playlist.Count > 0) PlayIndex(trackIndex + 1);
        }
    }
}
